package com.example.dicecontroller;
import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;import java.net.*;
public class MainActivity extends Activity{
 EditText ip;Spinner player;TextView msg;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,20,20,20);r.setBackgroundColor(Color.rgb(16,16,20));TextView h=t("🎛️ DICE CONTROLLER",28);r.addView(h);r.addView(t("Same Wi‑Fi par My Ludo app ka IP डालो",15));ip=new EditText(this);ip.setHint("Ludo IP e.g. 192.168.1.10");ip.setTextColor(Color.WHITE);r.addView(ip);r.addView(t("Kis player ko dice dena hai?",15));player=new Spinner(this);player.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Player 1","Player 2","Player 3","Player 4"}));r.addView(player);GridLayout g=new GridLayout(this);g.setColumnCount(2);r.addView(g);for(int n=1;n<=6;n++){Button x=new Button(this);x.setText("🎲 "+n);x.setTextSize(20);g.addView(x);final int v=n;x.setOnClickListener(z->send(v));}Button rnd=new Button(this);rnd.setText("RANDOM");r.addView(rnd);rnd.setOnClickListener(v->send(1+(int)(Math.random()*6)));msg=t("",16);r.addView(msg);setContentView(r);}
 TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(8,12,8,12);return v;}
 void send(int n){int p=player.getSelectedItemPosition()+1;new Thread(()->{try{DatagramSocket s=new DatagramSocket();byte[]b=(p+","+n).getBytes();s.send(new DatagramPacket(b,b.length,InetAddress.getByName(ip.getText().toString().trim()),45454));s.close();runOnUiThread(()->msg.setText("Player "+p+" ko dice "+n+" bheja"));}catch(Exception e){runOnUiThread(()->msg.setText("Connection error: "+e.getMessage()));}}).start();}
}